const SEP = '|#|';   // deve coincidere con quello nel corpo di MacroDroid
const raw = $json.body ?? $json.rawBody ?? $json;
let campi;
if (typeof raw === 'string') {
  campi = raw.split(SEP);
} else if (raw && typeof raw === 'object') {
  campi = [raw.titolo, raw.testo, raw.pacchetto, raw.ts];
} else {
  return [];
}
// I default valgono anche se il messaggio arriva con meno campi del previsto.
const [titolo = '', corpo = '', pkgRaw = '', tsRaw = ''] =
  campi.map(v => String(v ?? '').trim());
const pkg = pkgRaw.toLowerCase();
const testo = [titolo, corpo].filter(Boolean).join(' — ');
// Prova di MacroDroid: i segnaposto non sono stati sostituiti. Il webhook
// ha gia' risposto, quindi basta fermarsi: passarla a Processa Dati la
// farebbe fallire e attiverebbe il Guardiano.
if (/\{[a-z_]+\}/i.test(testo)) return [];
const RE_IMPORTO = /(?:€|\beuro?\b)\s*\d[\d.,]*|\d[\d.,]*\s*(?:€|\beuro?\b)/i;
if (!RE_IMPORTO.test(testo)) return [];
const impronta = (testo + '|' + pkg).replace(/\s+/g, '').slice(0, 120);
let ts = Number(tsRaw);
if (!ts || isNaN(ts)) ts = Date.now();
if (ts < 1e12) ts = ts * 1000;

// Advanzia: l'addebito avviene il 3 del mese successivo, quindi sposto la data.
const E_ADVANZIA = pkg.includes('advanzia') || /advanzia/i.test(titolo);
let data;
if (E_ADVANZIA) {
  const d = new Date(ts);
  // Date.UTC gestisce da solo il passaggio d'anno (dicembre → gennaio).
  data = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 3)).toISOString();
} else {
  data = new Date(ts).toISOString();
}

return [{ json: {
  fonte: 'push',
  // Il timestamp della notifica rende distinti due acquisti identici nello
  // stesso giorno (stesso importo, stessa app). Un reinvio della *stessa*
  // notifica porta lo stesso ts, quindi resta un doppione e viene scartato.
  id_esterno: 'push_' + impronta + '_' + Math.floor(ts / 1000),
  mittente: pkg || 'push',
  oggetto: titolo,
  testo,
  data
}}];
